"use strict";globalThis.onmessage=function(t){const{buf:n,sampleRate:o,id:e}=t.data;const r=new Float32Array(n);const c=applyHannWindow(r);const i=yinPitchDetect(c,o);let f=i.freq;let l=i.confidence;if(f>0){const t=harmonicProductSpectrum(c,o);if(t>0){f=reconcileDetectors(f,t)}}globalThis.postMessage({freq:f,confidence:l,id:e})};function applyHannWindow(t){const n=t.length;const o=new Float32Array(n);for(let e=0;e<n;e++){const r=.5*(1-Math.cos(2*Math.PI*e/(n-1)));o[e]=t[e]*r}return o}function yinDifferenceFunctionFFT(t,n){const o=t.length;const e=nextPow2(o*2);const r=new Float32Array(e);const c=new Float32Array(e);for(let n=0;n<o;n++)r[n]=t[n];fft(r,c,false);for(let t=0;t<e;t++){r[t]=r[t]*r[t]+c[t]*c[t];c[t]=0}fft(r,c,true);const i=new Float32Array(n);let f=0;let l=0;for(let o=0;o<n;o++){f+=t[o]*t[o];l+=t[o]*t[o]}i[0]=0;for(let o=1;o<n;o++){l+=t[o+n-1]*t[o+n-1]-t[o-1]*t[o-1];i[o]=f+l-2*r[o]/e}return i}function nextPow2(t){let n=1;while(n<t)n<<=1;return n}function fft(t,n,o){const e=t.length;const r=e>>1;for(let o=1,c=0;o<e;o++){let e=r;while(c&e){c^=e;e>>=1}c^=e;if(o<c){let e=t[o];t[o]=t[c];t[c]=e;e=n[o];n[o]=n[c];n[c]=e}}const c=o?1:-1;for(let o=2;o<=e;o<<=1){const r=o>>1;const i=c*Math.PI/r;const f=Math.cos(i);const l=Math.sin(i);for(let c=0;c<e;c+=o){let o=1,e=0;for(let i=0;i<r;i++){const s=c+i;const a=s+r;const u=o*t[a]-e*n[a];const h=o*n[a]+e*t[a];t[a]=t[s]-u;n[a]=n[s]-h;t[s]+=u;n[s]+=h;const y=o*f-e*l;e=o*l+e*f;o=y}}}}function yinCumulativeMeanNormalize(t,n){t[0]=1;let o=0;for(let e=1;e<n;e++){o+=t[e];t[e]*=e/o}}function yinFindTau(t,n,o){const e=.1;for(let r=n;r<o;r++){if(t[r]<e){while(r+1<o&&t[r+1]<t[r])r++;return r}}const r=.35;let c=Infinity;let i=-1;for(let e=n;e<o;e++){if(t[e]<c){c=t[e];i=e}}return c<r?i:-1}function yinParabolicInterpolation(t,n,o){if(n>0&&n<o-1){const o=t[n-1];const e=t[n];const r=t[n+1];const c=(o-r)/(2*(o-2*e+r));return Number.isFinite(c)?n+c:n}return n}function yinPitchDetect(t,n){const o=Math.floor(t.length/2);const e=yinDifferenceFunctionFFT(t,o);yinCumulativeMeanNormalize(e,o);const r=Math.floor(n/5e3);const c=Math.min(o-1,Math.floor(n/20));const i=yinFindTau(e,r,c);if(i===-1)return{freq:-1,confidence:0};const f=1-e[i];const l=yinParabolicInterpolation(e,i,o);const s=n/l;if(s<20||s>5e3)return{freq:-1,confidence:0};return{freq:s,confidence:f}}function harmonicProductSpectrum(t,n){const o=t.length;const e=nextPow2(o);const r=new Float32Array(e);const c=new Float32Array(e);for(let n=0;n<o;n++)r[n]=t[n];fft(r,c,false);const i=new Float32Array(e/2);for(let t=0;t<i.length;t++){i[t]=r[t]*r[t]+c[t]*c[t]}const f=4;const l=Math.floor(20*e/n);const s=Math.min(i.length/f,Math.floor(5e3*e/n));const a=new Float32Array(s);for(let t=l;t<s;t++){let n=i[t];for(let o=2;o<=f;o++){n*=i[t*o]||0}a[t]=n}let u=l;let h=0;for(let t=l;t<s;t++){if(a[t]>h){h=a[t];u=t}}if(h===0)return-1;if(u>0&&u<s-1){const t=a[u-1];const o=a[u];const r=a[u+1];const c=(t-r)/(2*(t-2*o+r));if(Number.isFinite(c)){return(u+c)*n/e}}return u*n/e}function reconcileDetectors(t,n){const o=t/n;if(o>1.8&&o<2.2)return n;if(o>.45&&o<.55)return n;if(o>2.8&&o<3.2)return n;return t}